    pictures?: Array<string>;
    /**
     * The axes it is sold along.
     */
    axes?: Array<ItemAxisInput>;
    /**
     * Its variants.
     */
    variants: Array<CatalogVariantInput>;
    /**
     * When and how it may be ordered.
     */
